import readItemList from "./controllers/readItems.js";
import setItem from "./controllers/setItem.js";
const policy = ["site"];
export default async function plugin(app) {
    app.route({
        method: "GET",
        url: "/db-list",
        config: { policy },
        handler: readItemList,
    });
    app.route({
        method: "GET",
        url: "/db-list/:id",
        config: { policy },
        handler: setItem,
    });
}
